import math
D = 12000
S = 1500
h = 0.2
p_undiscounted = 100
EOQ_base = math.sqrt(2 * D * S / (h * p_undiscounted))
price_tiers = [(0, 999, 100), (1000, 2499, 96), (2500, float('inf'), 94)]

def total_cost(Q):
    for lower, upper, price in price_tiers:
        if lower <= Q <= upper:
            p = price
            break
    else:
        raise ValueError('Order quantity out of range')
    return D * p + D / Q * S + Q / 2 * (h * p)

best_order_qty = None
min_total_cost = float('inf')
for Q in range(1, 4999):
    cost = total_cost(Q)
    if cost < min_total_cost:
        min_total_cost = cost
        best_order_qty = Q
orders_per_year = D / best_order_qty
assert abs(EOQ_base - math.sqrt(2 * D * S / (h * p_undiscounted))) < 1e-05, f'EOQ base mismatch: {EOQ_base} != {math.sqrt(2 * D * S / (h * p_undiscounted))}'
assert min_total_cost < total_cost(int(EOQ_base)), f'Min total cost not less than EOQ cost: {min_total_cost} >= {total_cost(int(EOQ_base))}'
RESULT = {'eoq_base': round(EOQ_base, 2), 'best_order_qty': best_order_qty, 'min_total_cost': round(min_total_cost, 2), 'orders_per_year': round(orders_per_year, 2)}
